# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


# ---
def make_student(last, first):
    ident = f"{last}-{first}"
    return Student(ident, last, first, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Alder", "Sam"),
        ]

    def test_sorted_by_last_name_and_split_into_rows(self):
        self.assertEqual(
            seating_rows(self.students, 2),
            ["Row 1: Alder, Sam | Dunmere, Piet", "Row 2: Halloway, Juno"],
        )

    def test_single_row_when_seats_exceed_students(self):
        rows = seating_rows(self.students, 10)
        self.assertEqual(rows, ["Row 1: Alder, Sam | Dunmere, Piet | Halloway, Juno"])

    def test_ties_break_on_first_name(self):
        pair = [make_student("Lowe", "Zed"), make_student("Lowe", "Amy")]
        self.assertEqual(seating_rows(pair, 2), ["Row 1: Lowe, Amy | Lowe, Zed"])

    def test_input_list_is_not_modified(self):
        seating_rows(self.students, 2)
        self.assertEqual(self.students[0].last_name, "Halloway")

    def test_zero_or_negative_seats_raise(self):
        for seats in (0, -3):
            with self.assertRaises(ValueError):
                seating_rows(self.students, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)


if __name__ == "__main__":
    unittest.main()
